503	// =========================================================================
504	//  PEER forward (oracle forward_for_bilevel:763-807) — soft top-k product-key
505	//  routing + expert MLP. Returns total_expert_out [N,1] and per-head saved
506	//  tensors needed by the backward.
507	// =========================================================================
508	struct PeerHeadSaved {
509	    Tensor query;        // [N, d_model]
510	    Tensor scores_a, scores_b;  // [N, pk_dim]
511	    Tensor top_a_idx, top_b_idx;// [N, topk]
512	    Tensor top_a_vals, top_b_vals; // [N, topk]
513	    Tensor soft_a, soft_b;      // [N, topk]
514	    Tensor expert_indices;      // [N, num_active] long
515	    Tensor routing_weights;     // [N, num_active]
516	    Tensor z;                   // [N, num_active, expert_hidden] relu hidden
517	    Tensor out;                 // [N, num_active] expert outputs (pre-routing)
518	};
519	
520	// =========================================================================
521	//  FORWARD-SAVE — runs the full meta-net forward and fills SavedActs. NO grad.
522	// =========================================================================
523	static SavedActs bilevel_forward_save(
524	    const Tensor& grad, const Tensor& sharpness, const Tensor& gru_state,
525	    const Tensor& input_proj_W, const Tensor& input_proj_b,
526	    const Tensor& csa_q_W, const Tensor& csa_k_W, const Tensor& csa_v_W,
527	    const Tensor& csa_compress_w, const Tensor& csa_idx_DQ,
528	    const Tensor& csa_idx_UQ, const Tensor& csa_idx_K, const Tensor& csa_out_W,
529	    const Tensor& hca_q_W, const Tensor& hca_k_W, const Tensor& hca_v_W,
530	    const Tensor& hca_out_W,
531	    const Tensor& gru_Wz, const Tensor& gru_bz, const Tensor& gru_Wr,
532	    const Tensor& gru_br, const Tensor& gru_Wh, const Tensor& gru_bh,
533	    int64_t d_model, int64_t num_heads,
534	    int64_t csa_compress, int64_t csa_window, int64_t csa_topk,
535	    int64_t hca_compress, int64_t indexer_rank)
536	{
537	    SavedActs S;
538	    const auto N = grad.numel();
539	    auto g = grad.reshape({-1}).to(torch::kFloat32);
540	    auto s = sharpness.reshape({-1}).to(torch::kFloat32);
541	    S.g_col = g; S.s_col = s;
542	
543	    auto sort_idx = g.abs().argsort();                    // ascending (oracle)
544	    S.sort_idx = sort_idx;
545	    S.unsort_idx = sort_idx.argsort();
546	    auto g_sorted = g.index_select(0, sort_idx);
547	    auto s_sorted = s.index_select(0, sort_idx);
548	    auto inp = torch::stack({g_sorted, s_sorted}, -1);    // [N, 2]
549	    auto x = linear_fwd(inp, input_proj_W, input_proj_b); // [N, d]
550	    S.x_sorted = x;
551	
552	    auto cf = csa_forward(x, csa_q_W, csa_k_W, csa_v_W, csa_compress_w,
553	                          csa_idx_DQ, csa_idx_UQ, csa_idx_K, num_heads,
554	                          csa_compress, csa_window, csa_topk);
555	    auto csa_out = linear_fwd(cf.ctx, csa_out_W);         // [N,d] sorted
556	    auto hf = hca_forward(x, hca_q_W, hca_k_W, hca_v_W, num_heads,
557	                          hca_compress, csa_window);
558	    auto hca_out = linear_fwd(hf.ctx, hca_out_W);
559	
560	    S.csa_ctx = csa_out.index_select(0, S.unsort_idx);    // [N,d] unsorted
561	    S.hca_ctx = hca_out.index_select(0, S.unsort_idx);
562	    S.csa_sel_idx = cf.sel;
563	    S.csa_probs = cf.attn;
564	    S.csa_denom = torch::zeros({N, num_heads}, x.options());
565	    S.hca_probs = hf.attn;
566	    S.hca_denom = torch::zeros({num_heads, N}, x.options());
567	
568	    // GRU
569	    auto gru_input = torch::cat({g.unsqueeze(-1), s.unsqueeze(-1),
570	                                 S.csa_ctx, S.hca_ctx}, -1);   // [N, gru_in]
571	    S.gru_input = gru_input;
572	    auto h_old = gru_state.reshape({-1}).to(torch::kFloat32);
573	    auto gru_hidden = h_old.size(0);
574	    auto h2d = h_old.unsqueeze(0).expand({N, gru_hidden}).contiguous();
575	    S.gru_h_old = h2d;
576	    auto xh = torch::cat({gru_input, h2d}, -1);
577	    auto z = torch::sigmoid(linear_fwd(xh, gru_Wz, gru_bz));
578	    auto r = torch::sigmoid(linear_fwd(xh, gru_Wr, gru_br));
579	    auto xrh = torch::cat({gru_input, r * h2d}, -1);
580	    auto h_tilde = torch::tanh(linear_fwd(xrh, gru_Wh, gru_bh));
581	    auto h_new = (1.0f - z) * h2d + z * h_tilde;
582	    S.gru_z = z; S.gru_r = r; S.gru_h_tilde = h_tilde; S.gru_new = h_new;
583	
584	    auto peer_input = torch::cat({h_new, S.csa_ctx, S.hca_ctx,
585	                                  g.unsqueeze(-1), s.unsqueeze(-1)}, -1);
586	    S.peer_input = peer_input;
587	    (void)d_model; (void)indexer_rank;
588	    return S;
589	}
