709	// =========================================================================
710	//  TOP-LEVEL BACKWARD DRIVER — consumes SavedActs + d_smart_grad, accumulates
711	//  all 24 weight-grad buffers. Pure hand-written reverse-mode VJP.
712	// =========================================================================
713	static void bilevel_backward_driver(
714	    const Tensor& d_smart_grad, float rescale, const SavedActs& S,
715	    // weights
716	    const Tensor& input_proj_W,
717	    const Tensor& csa_q_W, const Tensor& csa_k_W, const Tensor& csa_v_W,
718	    const Tensor& csa_compress_w, const Tensor& csa_idx_DQ,
719	    const Tensor& csa_idx_UQ, const Tensor& csa_idx_K, const Tensor& csa_out_W,
720	    const Tensor& hca_q_W, const Tensor& hca_k_W, const Tensor& hca_v_W,
721	    const Tensor& hca_out_W,
722	    const Tensor& gru_Wz, const Tensor& gru_Wr, const Tensor& gru_Wh,
723	    const std::vector<Tensor>& peer_Wq,
724	    const std::vector<Tensor>& prod_A, const std::vector<Tensor>& prod_B,
725	    const Tensor& expert_W1, const Tensor& expert_b1,
726	    const Tensor& expert_W2, const Tensor& expert_b2,
727	    int64_t d_model, int64_t num_heads, int64_t gru_hidden,
728	    int64_t pk_dim, int64_t topk, int64_t expert_hidden,
729	    int64_t csa_compress, int64_t csa_window, int64_t csa_topk,
730	    int64_t hca_compress, int64_t indexer_rank,
731	    // OUTPUT grads (zero-init, accumulate)
732	    Tensor& d_input_proj_W, Tensor& d_input_proj_b,
733	    Tensor& d_csa_q_W, Tensor& d_csa_k_W, Tensor& d_csa_v_W,
734	    Tensor& d_csa_compress_w, Tensor& d_csa_idx_DQ, Tensor& d_csa_idx_UQ,
735	    Tensor& d_csa_idx_K, Tensor& d_csa_out_W,
736	    Tensor& d_hca_q_W, Tensor& d_hca_k_W, Tensor& d_hca_v_W, Tensor& d_hca_out_W,
737	    Tensor& d_gru_Wz, Tensor& d_gru_bz, Tensor& d_gru_Wr, Tensor& d_gru_br,
738	    Tensor& d_gru_Wh, Tensor& d_gru_bh,
739	    std::vector<Tensor>& d_peer_Wq,
740	    std::vector<Tensor>& d_prod_A, std::vector<Tensor>& d_prod_B,
741	    Tensor& d_expert_W1, Tensor& d_expert_b1,
742	    Tensor& d_expert_W2, Tensor& d_expert_b2)
743	{
744	    const auto N = d_smart_grad.numel();
745	    auto dsg = d_smart_grad.reshape({-1}).to(torch::kFloat32);
746	    auto g = S.g_col, s = S.s_col;
747	
748	    // (1) smart_grad = g + rescale * total_expert_out  (total = mean over heads)
749	    //     d_total_expert_out = rescale * d_smart_grad   [N,1]
750	    //     (the +g term gives no meta-param grad)
751	    const int64_t num_peer_heads = (int64_t)peer_Wq.size();
752	    auto d_total = (dsg * rescale).reshape({N, 1});         // [N,1]
753	    auto d_head_out = d_total / (double)num_peer_heads;     // each head shares
754	
755	    // (2) PEER per-head backward → accumulate d wrt peer_input.
756	    auto d_peer_input = torch::zeros_like(S.peer_input);    // [N, peer_in]
757	    for (int64_t h = 0; h < num_peer_heads; ++h) {
758	        auto dpi = peer_head_backward(
759	            S.peer_input, g, peer_Wq[h], prod_A[h], prod_B[h],
760	            expert_W1, expert_b1, expert_W2, expert_b2,
761	            d_model, pk_dim, topk, expert_hidden, d_head_out,
762	            d_peer_Wq[h], d_prod_A[h], d_prod_B[h],
763	            d_expert_W1, d_expert_b1, d_expert_W2, d_expert_b2);
764	        d_peer_input += dpi;
765	    }
766	
767	    // (3) peer_input = cat(gru_new, csa_ctx, hca_ctx, g, s)
768	    int64_t off = 0;
769	    auto d_gru_new = d_peer_input.index({Slice(), Slice(off, off + gru_hidden)});
770	    off += gru_hidden;
771	    auto d_csa_ctx = d_peer_input.index({Slice(), Slice(off, off + d_model)}).clone();
772	    off += d_model;
773	    auto d_hca_ctx = d_peer_input.index({Slice(), Slice(off, off + d_model)}).clone();
774	    off += d_model;
775	    // g/s columns carry no meta-param grad.
776	
777	    // (4) GRU backward. h_new = (1-z)*h_old + z*h_tilde
778	    auto z = S.gru_z, r = S.gru_r, h_tilde = S.gru_h_tilde, h_old = S.gru_h_old;
779	    auto dnew = d_gru_new;                                  // [N, gru_hidden]
780	    auto d_z = dnew * (h_tilde - h_old);                   // [N,H]
781	    auto d_h_tilde = dnew * z;                             // via z*h_tilde
782	    auto d_h_old = dnew * (1.0f - z);                      // via (1-z)*h_old
783	
784	    // h_tilde = tanh(Wh @ xrh + bh); xrh = cat(gru_input, r*h_old)
785	    auto d_pre_h = d_h_tilde * (1.0f - h_tilde * h_tilde); // [N,H]
786	    d_gru_bh.add_(d_pre_h.sum(0));
787	    auto gru_input = S.gru_input;
788	    auto xrh = torch::cat({gru_input, r * h_old}, -1);
789	    d_gru_Wh.add_(torch::mm(d_pre_h.t(), xrh));
790	    auto d_xrh = torch::mm(d_pre_h, gru_Wh);               // [N, gru_in + H]
791	    auto gru_in_dim = gru_input.size(1);
792	    auto d_gru_input = d_xrh.index({Slice(), Slice(0, gru_in_dim)}).clone();
793	    auto d_rh = d_xrh.index({Slice(), Slice(gru_in_dim, gru_in_dim + gru_hidden)});
794	    auto d_r = d_rh * h_old;
795	    d_h_old += d_rh * r;
796	
797	    // z = sigmoid(Wz @ xh + bz); xh = cat(gru_input, h_old)
798	    auto d_pre_z = d_z * z * (1.0f - z);                   // [N,H]
799	    auto xh = torch::cat({gru_input, h_old}, -1);
800	    d_gru_bz.add_(d_pre_z.sum(0));
801	    d_gru_Wz.add_(torch::mm(d_pre_z.t(), xh));
802	    auto d_xh_z = torch::mm(d_pre_z, gru_Wz);
803	    d_gru_input += d_xh_z.index({Slice(), Slice(0, gru_in_dim)});
804	    d_h_old += d_xh_z.index({Slice(), Slice(gru_in_dim, gru_in_dim + gru_hidden)});
805	
806	    // r = sigmoid(Wr @ xh + br)
807	    auto d_pre_r = d_r * r * (1.0f - r);
808	    d_gru_br.add_(d_pre_r.sum(0));
809	    d_gru_Wr.add_(torch::mm(d_pre_r.t(), xh));
810	    auto d_xh_r = torch::mm(d_pre_r, gru_Wr);
811	    d_gru_input += d_xh_r.index({Slice(), Slice(0, gru_in_dim)});
812	    d_h_old += d_xh_r.index({Slice(), Slice(gru_in_dim, gru_in_dim + gru_hidden)});
813	    // d_h_old flows into gru_state — not a meta-param of THIS step (carried).
814	
815	    // (5) gru_input = cat(g, s, csa_ctx, hca_ctx)
816	    int64_t go = 0;
817	    go += 1;  // g
818	    go += 1;  // s
819	    d_csa_ctx += d_gru_input.index({Slice(), Slice(go, go + d_model)});
820	    go += d_model;
821	    d_hca_ctx += d_gru_input.index({Slice(), Slice(go, go + d_model)});
822	    go += d_model;
823	
824	    // (6) unsort: csa_ctx = csa_out[unsort_idx] → d_csa_out (sorted) via sort_idx
825	    //     d_csa_out_sorted[sort_idx[i]] gets d_csa_ctx[i]? We have csa_ctx =
826	    //     csa_out.index_select(0, unsort_idx). Inverse: d_csa_out = scatter by
827	    //     unsort_idx.  Equivalent: d_csa_out = d_csa_ctx.index_select(0, sort_idx).
828	    auto d_csa_out_sorted = d_csa_ctx.index_select(0, S.sort_idx);  // [N,d] sorted
829	    auto d_hca_out_sorted = d_hca_ctx.index_select(0, S.sort_idx);
830	
831	    // (7) recompute CSA/HCA forwards from x_sorted, then attention backward.
832	    auto x = S.x_sorted;
833	    auto d_x = torch::zeros_like(x);                       // [N, d] grad wrt x_sorted
834	
835	    auto cf = csa_forward(x, csa_q_W, csa_k_W, csa_v_W, csa_compress_w,
836	                          csa_idx_DQ, csa_idx_UQ, csa_idx_K, num_heads,
837	                          csa_compress, csa_window, csa_topk);
838	    // csa_out = ctx @ out_W.t() → d_out_W, d_ctx
839	    d_csa_out_W.add_(torch::mm(d_csa_out_sorted.t(), cf.ctx));
840	    auto d_csa_ctx_pre = torch::mm(d_csa_out_sorted, csa_out_W);    // [N,d]
841	    csa_backward(x, cf, csa_q_W, csa_k_W, csa_v_W, csa_compress_w,
842	                 csa_idx_DQ, csa_idx_UQ, csa_idx_K, num_heads,
843	                 d_csa_ctx_pre, d_csa_q_W, d_csa_k_W, d_csa_v_W,
844	                 d_csa_compress_w, d_csa_idx_DQ, d_csa_idx_UQ, d_csa_idx_K, d_x);
845	
846	    auto hf = hca_forward(x, hca_q_W, hca_k_W, hca_v_W, num_heads,
847	                          hca_compress, csa_window);
848	    d_hca_out_W.add_(torch::mm(d_hca_out_sorted.t(), hf.ctx));
849	    auto d_hca_ctx_pre = torch::mm(d_hca_out_sorted, hca_out_W);
850	    hca_backward(x, hf, hca_q_W, hca_k_W, hca_v_W, num_heads, d_hca_ctx_pre,
851	                 d_hca_q_W, d_hca_k_W, d_hca_v_W, d_x);
852	
853	    // (8) input_proj backward.
854	    //  x = inp @ input_proj_W.t() + b, inp = stack(g_sorted, s_sorted).
855	    //  d_input_proj_W[d, 0] += Σ_i d_x[i,d] * g_sorted[i]
856	    //  d_input_proj_W[d, 1] += Σ_i d_x[i,d] * s_sorted[i]
857	    //  d_input_proj_b[d]    += Σ_i d_x[i,d]
858	    auto g_sorted = g.index_select(0, S.sort_idx);
859	    auto s_sorted = s.index_select(0, S.sort_idx);
860	    // d_input_proj_W: [d_model, 2]
861	    auto dW0 = (d_x * g_sorted.unsqueeze(1)).sum(0);       // [d]
862	    auto dW1 = (d_x * s_sorted.unsqueeze(1)).sum(0);       // [d]
863	    d_input_proj_W.add_(torch::stack({dW0, dW1}, 1));      // [d, 2]
864	    d_input_proj_b.add_(d_x.sum(0));                       // [d]
865	
866	    (void)indexer_rank;
867	}
