777	// Out projection: ctx[t,d] = sum_k out_W[d,k]*concat[t,k]. (== sg2_stage_project)
778	template <typename Dims>
779	__device__ __forceinline__ void sg2_stage_out_proj(
780	    const float* __restrict__ concat, const float* __restrict__ out_W,
781	    float* __restrict__ ctx, int N) {
782	    sg2_stage_project<Dims>(concat, out_W, ctx, N);
783	}
