785	// Matrix-GRU forward (per element row). gru_input = [g, s, csa_ctx, hca_ctx]
786	// (all in SORTED order); h_old = gru_state[src] in sorted order (src=perm[r]).
787	//   z = sigmoid(xh @ Wz.T + bz), r = sigmoid(xh @ Wr.T + br),
788	//   h̃ = tanh(xrh @ Wh.T + bh),  h_new = (1-z)*h_old + z*h̃
789	// Owner thread per sorted row r computes the whole gru_hidden vector. The new
790	// state is written back to gru_state in ORIGINAL order (gru_state[src]).
791	template <typename Dims, typename WeightsT>
792	__device__ __forceinline__ void sg2_stage_gru(
793	    const WeightsT& w,
794	    const float* __restrict__ g_sorted,   // [N]
795	    const float* __restrict__ s_sorted,   // [N]
796	    const float* __restrict__ csa_ctx,    // [N, d_model] (sorted)
797	    const float* __restrict__ hca_ctx,    // [N, d_model] (sorted)
798	    const int* __restrict__ perm,         // [N] sorted-row -> original-row
799	    float* __restrict__ gru_state,        // [N, gru_hidden] ORIGINAL order (in/out)
800	    float* __restrict__ new_gru,          // [N, gru_hidden] SORTED order (out)
801	    int N) {
802	    constexpr int d = Dims::d_model;
803	    constexpr int gh = Dims::gru_hidden;
804	    constexpr int gi = Dims::gru_in;        // 2 + 2*d
805	    constexpr int xin = gi + gh;            // concat width into the gates
806	    for (int r = threadIdx.x; r < N; r += blockDim.x) {
807	        const int src = perm[r];
808	        // Build gru_input row [g, s, csa(d), hca(d)] and h_old.
809	        float xin_buf[xin];
810	        xin_buf[0] = g_sorted[r];
811	        xin_buf[1] = s_sorted[r];
812	        #pragma unroll
813	        for (int k = 0; k < d; ++k) xin_buf[2 + k]     = csa_ctx[r * d + k];
814	        #pragma unroll
815	        for (int k = 0; k < d; ++k) xin_buf[2 + d + k] = hca_ctx[r * d + k];
816	        float h_old[gh];
817	        #pragma unroll
818	        for (int k = 0; k < gh; ++k) h_old[k] = gru_state[src * gh + k];
819	        // xh = [gru_input, h_old]
820	        #pragma unroll
821	        for (int k = 0; k < gh; ++k) xin_buf[gi + k] = h_old[k];
822	        // z, r gates: linear over xh (Wz/Wr are [gh, xin] row-major).
823	        float zg[gh], rg[gh];
824	        #pragma unroll
825	        for (int o = 0; o < gh; ++o) {
826	            float az = w.gru_bz[o], ar = w.gru_br[o];
827	            #pragma unroll
828	            for (int k = 0; k < xin; ++k) {
829	                az += w.gru_Wz[o * xin + k] * xin_buf[k];
830	                ar += w.gru_Wr[o * xin + k] * xin_buf[k];
831	            }
832	            // Accurate sigmoid (expf, NOT ptx_expf): the reference matrix-GRU
833	            // (csa_hca_step_one) uses torch::sigmoid — an accurate transcendental.
834	            // Matching it with expf keeps the GRU on the reference's precision;
835	            // ptx_expf (ex2.approx) here would diverge invisibly to the fp64 mirror
836	            // and only surface at the 1e-5 GPU parity gate. (tanhf below is already
837	            // the accurate intrinsic, matching torch::tanh.)
838	            zg[o] = 1.0f / (1.0f + expf(-az));
839	            rg[o] = 1.0f / (1.0f + expf(-ar));
840	        }
841	        // xrh = [gru_input, r*h_old]; overwrite the h_old tail with r*h_old.
842	        #pragma unroll
843	        for (int k = 0; k < gh; ++k) xin_buf[gi + k] = rg[k] * h_old[k];
844	        // h̃ = tanh(xrh @ Wh.T + bh), then h_new = (1-z)*h_old + z*h̃.
845	        #pragma unroll
846	        for (int o = 0; o < gh; ++o) {
847	            float ah = w.gru_bh[o];
848	            #pragma unroll
849	            for (int k = 0; k < xin; ++k) ah += w.gru_Wh[o * xin + k] * xin_buf[k];
850	            const float ht = tanhf(ah);
851	            const float hn = (1.0f - zg[o]) * h_old[o] + zg[o] * ht;
852	            new_gru[r * gh + o] = hn;       // sorted order (feeds PEER)
853	            gru_state[src * gh + o] = hn;   // persist in ORIGINAL order
854	        }
855	    }
856	}
857	
858	// PEER routing + experts (per element row, sorted order). Mirrors
859	// detail::peer_expert_forward + the eager forward exactly:
860	//   peer_input = [new_gru, csa_ctx, hca_ctx, g, s]  (width peer_in)
861	//   per head: query = peer_input @ Wq.T (d_model wide); q_a=[:half], q_b=[half:];
862	//     sa = q_a @ A.T, sb = q_b @ B.T (each [pk_dim]); top-k of each → ka,kb;
863	//     soft = softmax(top*10); expert = a_idx*pk_dim + b_idx (k×k); routing =
864	//     soft_a⊗soft_b; per expert: ReLU MLP on scalar g; out = Σ routing*mlp;
865	//   head outputs averaged ÷ num_peer_heads; expert_out *= rescale.
866	// Owner thread per row r. The MLP input scalar is g_sorted[r] (matches eager).
867	template <typename Dims, typename WeightsT>
868	__device__ __forceinline__ void sg2_stage_peer(
869	    const WeightsT& w,
870	    const float* __restrict__ new_gru,    // [N, gru_hidden] sorted
871	    const float* __restrict__ csa_ctx,    // [N, d_model] sorted
872	    const float* __restrict__ hca_ctx,    // [N, d_model] sorted
873	    const float* __restrict__ g_sorted,   // [N]
874	    const float* __restrict__ s_sorted,   // [N]
875	    float* __restrict__ expert_out,       // [N] sorted (out)
876	    float rescale, int N) {
877	    constexpr int d = Dims::d_model;
878	    constexpr int gh = Dims::gru_hidden;
879	    constexpr int pin = Dims::peer_in;
880	    constexpr int half = Dims::d_model / 2;
881	    constexpr int pkd = Dims::pk_dim;
882	    constexpr int K = Dims::peer_topk;
883	    const float T = 10.0f;
884	    for (int r = threadIdx.x; r < N; r += blockDim.x) {
885	        // Build peer_input row.
886	        float pin_buf[pin];
887	        int o = 0;
888	        #pragma unroll
889	        for (int k = 0; k < gh; ++k) pin_buf[o++] = new_gru[r * gh + k];
890	        #pragma unroll
891	        for (int k = 0; k < d; ++k)  pin_buf[o++] = csa_ctx[r * d + k];
892	        #pragma unroll
893	        for (int k = 0; k < d; ++k)  pin_buf[o++] = hca_ctx[r * d + k];
894	        pin_buf[o++] = g_sorted[r];
895	        pin_buf[o++] = s_sorted[r];
896	
897	        const float gval = g_sorted[r];   // expert-MLP scalar input
898	        float head_sum = 0.0f;
899	        for (int h = 0; h < Dims::num_peer_heads; ++h) {
900	            const float* Wq = w.peer_query_Ws + (int64_t)h * d * pin;
901	            const float* A  = w.prod_keys_A   + (int64_t)h * pkd * half;
902	            const float* B  = w.prod_keys_B   + (int64_t)h * pkd * half;
903	            // query = Wq @ peer_input  (Wq is [d_model, peer_in] row-major).
904	            float query[d];
905	            #pragma unroll
906	            for (int oc = 0; oc < d; ++oc) {
907	                float acc = 0.0f;
908	                #pragma unroll
909	                for (int k = 0; k < pin; ++k) acc += Wq[oc * pin + k] * pin_buf[k];
910	                query[oc] = acc;
911	            }
912	            // scores_a[na] = q_a @ A.T ; scores_b[nb] = q_b @ B.T (na=nb=pk_dim).
913	            float sa[pkd], sb[pkd];
914	            #pragma unroll
915	            for (int n = 0; n < pkd; ++n) {
916	                float aa = 0.0f, bb = 0.0f;
917	                #pragma unroll
918	                for (int k = 0; k < half; ++k) {
919	                    aa += query[k]        * A[n * half + k];
920	                    bb += query[half + k] * B[n * half + k];
921	                }
922	                sa[n] = aa; sb[n] = bb;
923	            }
924	            // top-k of sa and sb (descending insertion), K = peer_topk.
925	            const int ka = (K < pkd) ? K : pkd;
926	            const int kb = ka;  // pk_dim symmetric
927	            float ta_v[K]; int ta_i[K];
928	            float tb_v[K]; int tb_i[K];
929	            #pragma unroll
930	            for (int i = 0; i < K; ++i) {
931	                ta_v[i] = -INFINITY; ta_i[i] = 0;
932	                tb_v[i] = -INFINITY; tb_i[i] = 0;
933	            }
934	            for (int n = 0; n < pkd; ++n) {
935	                if (sa[n] > ta_v[ka - 1]) {
936	                    int p = ka - 1;
937	                    while (p > 0 && ta_v[p - 1] < sa[n]) { ta_v[p]=ta_v[p-1]; ta_i[p]=ta_i[p-1]; --p; }
938	                    ta_v[p] = sa[n]; ta_i[p] = n;
939	                }
940	                if (sb[n] > tb_v[kb - 1]) {
941	                    int p = kb - 1;
942	                    while (p > 0 && tb_v[p - 1] < sb[n]) { tb_v[p]=tb_v[p-1]; tb_i[p]=tb_i[p-1]; --p; }
943	                    tb_v[p] = sb[n]; tb_i[p] = n;
944	                }
945	            }
946	            // softmax(top*T) per axis.
947	            float soft_a[K], soft_b[K];
948	            {
949	                float ma = ta_v[0], mb = tb_v[0];   // sorted descending → [0] is max
950	                float za = 0.0f, zb = 0.0f;
951	                // Accurate exp (expf, NOT ptx_expf): the reference PEER routing
952	                // (detail::peer_expert_forward) uses torch::softmax — accurate.
953	                // ptx_expf with the *T=10 amplification would diverge invisibly to
954	                // the fp64 mirror and only bite at the GPU parity gate.
955	                for (int i = 0; i < ka; ++i) { soft_a[i] = expf((ta_v[i]-ma)*T); za += soft_a[i]; }
956	                for (int i = 0; i < kb; ++i) { soft_b[i] = expf((tb_v[i]-mb)*T); zb += soft_b[i]; }
957	                for (int i = 0; i < ka; ++i) soft_a[i] /= za;
958	                for (int i = 0; i < kb; ++i) soft_b[i] /= zb;
959	            }
960	            // k×k Cartesian experts + routing-weighted MLP, accumulate.
961	            float head_out = 0.0f;
962	            for (int ia = 0; ia < ka; ++ia) {
963	                for (int ib = 0; ib < kb; ++ib) {
964	                    int eidx = ta_i[ia] * pkd + tb_i[ib];
965	                    if (eidx < 0) eidx = 0;
966	                    if (eidx > Dims::num_experts - 1) eidx = Dims::num_experts - 1;
967	                    const float rw = soft_a[ia] * soft_b[ib];
968	                    // expert MLP: ReLU(W1*g + b1) then W2·z + b2. W1/W2 are
969	                    // [num_experts, expert_hidden]; per-element scalar input g.
970	                    const float* W1 = w.expert_W1 + (int64_t)eidx * Dims::expert_hidden;
971	                    const float* b1 = w.expert_b1 + (int64_t)eidx * Dims::expert_hidden;
972	                    const float* W2 = w.expert_W2 + (int64_t)eidx * Dims::expert_hidden;
973	                    const float  b2 = w.expert_b2[eidx];
974	                    float mlp = b2;
975	                    #pragma unroll
976	                    for (int hdt = 0; hdt < Dims::expert_hidden; ++hdt) {
977	                        float z = W1[hdt] * gval + b1[hdt];
978	                        z = (z > 0.0f) ? z : 0.0f;   // ReLU
979	                        mlp += W2[hdt] * z;
980	                    }
981	                    head_out += rw * mlp;
982	                }
983	            }
984	            head_sum += head_out;
985	        }
986	        head_sum /= (float)Dims::num_peer_heads;
987	        expert_out[r] = head_sum * rescale;
988	    }
989	}
